"""Artifact model tracking files generated by analysis runs."""

import uuid
from datetime import datetime, timezone
from typing import Optional, TYPE_CHECKING
from sqlalchemy import String, DateTime, ForeignKey
from sqlalchemy.orm import Mapped, mapped_column, relationship
from backend.app.database.base import Base

if TYPE_CHECKING:
    from backend.app.models.analysis import Analysis


def get_utc_now() -> datetime:
    """Return current UTC timestamp with timezone."""
    return datetime.now(timezone.utc)


class Artifact(Base):
    """Artifact record linking derived files (difference maps, plots, crops) to an Analysis or ROI."""

    __tablename__ = "artifacts"

    id: Mapped[str] = mapped_column(
        String(36), primary_key=True, default=lambda: str(uuid.uuid4())
    )
    analysis_id: Mapped[Optional[str]] = mapped_column(
        String(36), ForeignKey("analyses.id", ondelete="CASCADE"), index=True, nullable=True
    )
    artifact_type: Mapped[str] = mapped_column(
        String(64), nullable=False
    )  # e.g., DIFFERENCE_MAP, HEATMAP, CIRCUIT_DIAGRAM, ROI_CROP, METRICS_JSON
    file_path: Mapped[str] = mapped_column(String(512), nullable=False)
    stored_filename: Mapped[str] = mapped_column(String(255), nullable=False)
    sha256_hash: Mapped[str] = mapped_column(String(64), nullable=False)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=get_utc_now, nullable=False
    )

    # Relationships
    analysis: Mapped[Optional["Analysis"]] = relationship("Analysis", back_populates="artifacts")

    def __repr__(self) -> str:
        return f"<Artifact(type='{self.artifact_type}', filename='{self.stored_filename}')>"

